-- PostgreSQL 16+; illustrative executable baseline migration, not entire production schema.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), code text NOT NULL, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh', UNIQUE(customer_id,code), UNIQUE(id,customer_id));
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), code text NOT NULL UNIQUE, name text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','planned','active','on_hold','completed','cancelled')), version int NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(id,customer_id));
CREATE TABLE project_sites (project_id uuid NOT NULL, site_id uuid NOT NULL, customer_id uuid NOT NULL, PRIMARY KEY(project_id,site_id), FOREIGN KEY(project_id,customer_id) REFERENCES projects(id,customer_id), FOREIGN KEY(site_id,customer_id) REFERENCES sites(id,customer_id));
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), parent_id uuid REFERENCES locations(id), kind text NOT NULL CHECK(kind IN ('building','floor','room','rack','other')), code text NOT NULL, UNIQUE(site_id,code), UNIQUE(id,site_id));
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), asset_code text NOT NULL UNIQUE, manufacturer text NOT NULL, model text NOT NULL, serial_number text, status text NOT NULL DEFAULT 'in_stock' CHECK(status IN ('received','in_stock','assigned','installed','active','repair','replaced','retired')), version int NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(id,customer_id));
CREATE INDEX idx_assets_serial ON assets(manufacturer,model,serial_number) WHERE serial_number IS NOT NULL;
CREATE TABLE asset_placements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id), location_id uuid NOT NULL REFERENCES locations(id), valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, actor_id uuid NOT NULL, reason text NOT NULL, CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE UNIQUE INDEX one_active_placement_per_asset ON asset_placements(asset_id) WHERE valid_to IS NULL;
CREATE TABLE asset_replacements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), old_asset_id uuid NOT NULL REFERENCES assets(id), new_asset_id uuid NOT NULL REFERENCES assets(id), work_order_ref uuid, actor_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), CHECK(old_asset_id<>new_asset_id));
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), code text NOT NULL, name text NOT NULL, UNIQUE(customer_id,code));
CREATE TABLE configuration_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), asset_id uuid REFERENCES assets(id), ci_type text NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE service_ci (service_id uuid NOT NULL REFERENCES services(id), ci_id uuid NOT NULL REFERENCES configuration_items(id), PRIMARY KEY(service_id,ci_id));
CREATE TABLE ci_relations (source_ci_id uuid NOT NULL REFERENCES configuration_items(id), target_ci_id uuid NOT NULL REFERENCES configuration_items(id), relation_type text NOT NULL, PRIMARY KEY(source_ci_id,target_ci_id,relation_type), CHECK(source_ci_id<>target_ci_id));
CREATE TABLE diagrams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites(id), kind text NOT NULL CHECK(kind IN ('floor','rack','topology')), title text NOT NULL);
CREATE TABLE diagram_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), diagram_id uuid NOT NULL REFERENCES diagrams(id), revision int NOT NULL CHECK(revision>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','approved','superseded')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(diagram_id,revision));
CREATE TABLE diagram_nodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES diagram_versions(id), asset_id uuid REFERENCES assets(id), ci_id uuid REFERENCES configuration_items(id), x numeric NOT NULL, y numeric NOT NULL, CHECK(asset_id IS NOT NULL OR ci_id IS NOT NULL));
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id), site_id uuid, code text NOT NULL UNIQUE, type text NOT NULL CHECK(type IN ('incident','service_request')), priority text NOT NULL CHECK(priority IN ('p1','p2','p3','p4')), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','triaged','assigned','in_progress','resolved','closed')), version int NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(site_id,customer_id) REFERENCES sites(id,customer_id));
CREATE TABLE ticket_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_id uuid NOT NULL REFERENCES tickets(id), actor_id uuid, event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dedupe_key text NOT NULL UNIQUE, event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','delivered','dead')), attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
CREATE INDEX idx_outbox_due ON outbox_events(status,available_at) WHERE status IN ('pending','processing');
COMMIT;
-- Follow-up migrations must add RBAC, contracts/SLA, checklist, acceptance, documents and audit.
-- Cross-customer asset-placement and CI/service invariants require additional composite keys/guards before production.
